mapper.select:
select * from coupon_order

    and number like concat('%', #{number}, '%')
    and username like concat('%', #{username}, '%')
    and status = #{status}
    and create_time >= #{beginTime}
    and create_time <= #{endTime}
 order by create_time desc

select * from coupon_order
where user_id = #{userId}

    and status = #{status}

order by create_time desc
